(2, 26, 'Nephrology Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'One of the following is a sign of clotting in the extra corporal circuit', '["Extremely dark blood in the circuit", "Clear dialyzer on flushing with fluid", "Clear dialyzer on flushing with saline", "Rapid filling of the transducer monitors with blood"]'::jsonb, 3, 'The correct answer is: Rapid filling of the transducer monitors with blood.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
(2, 27, 'Nephrology Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NNP 415 · Principles & Practice of Nephrology Nursing I', 'If a patient develops hypotension during dialysis, the initial intervention is to:', '["Increase the rate of ultrafiltration", "Increase the ultrafiltration rate to finish the session faster", "Increase the dialysate temperature", "Place the patient in Trendelenburg position and reduce ultrafiltration"]'::jsonb, 3, 'The correct answer is: Place the patient in Trendelenburg position and reduce ultrafiltration.', 'NNP 415 · Principles & Practice of Nephrology Nursing I'),
