(2, 45, 'Nephrology Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A patient with Stage 5 CKD is experiencing extreme pruritus and has several areas of crystallized white deposits on the skin. As the nurse, you know this is due to excessive amounts of what substance found in the blood?', '["Urea", "Calcium", "Erythropoietin", "Phosphate"]'::jsonb, 0, 'The correct answer is: Urea.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 46, 'Nephrology Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Which of the following is NOT a common cause of chronic kidney disease (CKD)?', '["Hypertension", "Diabetes", "Acute bronchitis", "Glomerulonephritis"]'::jsonb, 2, 'The correct answer is: Acute bronchitis.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 47, 'Nephrology Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A patient with CKD is admitted with severe hypocalcemia. Which of the following signs is a classic indicator of hypocalcemia?', '["Brudzinski''s sign", "Cullen''s sign", "Babinski reflex", "Trousseau''s sign"]'::jsonb, 3, 'The correct answer is: Trousseau''s sign.', 'NNP 417 · Medical-Surgical Nephrology I'),
