(2, 56, 'Nephrology Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'In the RIFLE criteria for AKI, “I” (Injury) is characterized by which of the following?', '["GFR increase by 10%", "75% reduction in GFR", "50% reduction in GFR", "25% reduction in GFR"]'::jsonb, 2, 'The correct answer is: 50% reduction in GFR.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 57, 'Nephrology Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Which life-threatening disorder commonly occurs in AKI', '["Hypokalaemia", "Hyperkalaemia", "Hyponatraemia", "Hypernatraemia"]'::jsonb, 1, 'The correct answer is: Hyperkalaemia.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 58, 'Nephrology Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Diabetic nephropathy primarily affects which structure of the kidney?', '["Glomerulus", "Loop of Henle", "Ureter", "Collecting duct"]'::jsonb, 0, 'The correct answer is: Glomerulus.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 59, 'Nephrology Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Which of the following is a reversible cause of AKI often found in hospitalized patients?', '["Urinary obstruction", "Glomerulonephritis", "Hypertensive nephrosclerosis", "Diabetic nephropathy"]'::jsonb, 0, 'The correct answer is: Urinary obstruction.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 60, 'Nephrology Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Which of the following is a common cause of chronic kidney disease (CKD)?', '["Gastrointestinal diseases", "Hypertension", "Hyperthyroidism", "Acute infections"]'::jsonb, 1, 'Hypertension and diabetes are the leading causes of CKD globally.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 61, 'Nephrology Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Which picture best fits post-streptococcal glomerulonephritis?', '["Polyuria with dilute urine", "Normal complement with fatty casts", "Low C3 with raised ASO titre", "High serum albumin"]'::jsonb, 2, 'The correct answer is: Low C3 with raised ASO titre.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 62, 'Nephrology Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A urine specific gravity test helps assess:', '["Protein levels in blood", "Concentration of urine", "Glucose levels", "Blood pressure"]'::jsonb, 1, 'Urine specific gravity measures how concentrated or diluted the urine is.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 63, 'Nephrology Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'the estimated GFR of someone with CKD stage 5 is', '["90+", "15 - 29", "60 - 89", "<15"]'::jsonb, 3, 'The correct answer is: <15.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 64, 'Nephrology Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'In kidney disease, an elevated BUN level often indicates:', '["Impaired renal function", "Low protein intake", "Normal kidney function", "High red blood cell production"]'::jsonb, 0, 'The correct answer is: Impaired renal function.', 'NNP 417 · Medical-Surgical Nephrology I'),
