(2, 66, 'Nephrology Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'When assessing a patient with chronic kidney disease who reports increasing fatigue, the nurse''s priority assessment should include:', '["Monitoring potassium intake", "Checking urine for proteinuria", "Evaluating serum hemoglobin and hematocrit levels", "Evaluating calcium and phosphate levels"]'::jsonb, 2, 'The correct answer is: Evaluating serum hemoglobin and hematocrit levels.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 67, 'Nephrology Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Which finding does NOT fit nephrotic syndrome?', '["Heavy proteinuria", "RBC casts with hypertension", "Hypoalbuminaemia", "Generalised oedema"]'::jsonb, 1, 'The correct answer is: RBC casts with hypertension.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 68, 'Nephrology Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Prerenal acute kidney injury is often caused by:', '["Direct kidney trauma", "Reduced blood flow to the kidneys", "Obstruction in the urinary tract", "Infections within the kidney"]'::jsonb, 1, 'The correct answer is: Reduced blood flow to the kidneys.', 'NNP 417 · Medical-Surgical Nephrology I'),
