(2, 72, 'Nephrology Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'A haemodialysis client has a newly created left arm fistula. The nurse monitors the affected extremity for which signs and symptoms that indicate a complication related to stealing syndrome?', '["Warmth, redness, and pain", "Aching pain, pallor, and oedema", "Oedema and purplish discoloration", "Pallor, diminished pulse. and pain"]'::jsonb, 3, 'The correct answer is: Pallor, diminished pulse. and pain.', 'NNP 417 · Medical-Surgical Nephrology I'),
(2, 73, 'Nephrology Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NNP 417 · Medical-Surgical Nephrology I', 'Which of the following factors causes the nausea associated with renal failure?', '["Gastric ulcers from stress", "Gastric ulcers", "Electrolyte imbalances", "Accumulation of waste products"]'::jsonb, 3, 'The correct answer is: Accumulation of waste products.', 'NNP 417 · Medical-Surgical Nephrology I'),
