(2, 80, 'Nephrology Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'In patients with CKD, the restriction of which electrolyte is often necessary?', '["Chloride", "Sodium", "Magnesium", "Phosphate"]'::jsonb, 3, 'High phosphate levels are common in CKD, leading to the need for dietary', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
(2, 81, 'Nephrology Nursing Mock — Day 1 Afternoon (Nov 2026)', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing', 'A person with chronic kidney disease would need to limit their dietary intake of this nutrient or risk getting high blood pressure.', '["Phosphorus", "Sodium", "Protein", "Potassium"]'::jsonb, 1, 'The correct answer is: Sodium.', 'NNP 416 · Nutrition and Dietetics in Nephrology Nursing'),
