(1, 1, 'Nephrology Nursing Mock — Day 2 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'The client with chronic renal failure has an indwelling catheter for peritoneal dialysis in the abdomen. The client spills water on the catheter dressing while bathing. The nurse should immediately:', '["Flush the peritoneal dialysis catheter", "Change the dressing", "Scrub the catheter with povidone-iodine", "Reinforce the dressing"]'::jsonb, 1, 'The correct answer is: Change the dressing.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 2, 'Nephrology Nursing Mock — Day 2 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'The commonest cause of PD catheter outflow failure is:', '["Constipation", "Fever", "Hypokalaemia", "Hypertension"]'::jsonb, 0, 'The correct answer is: Constipation.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 3, 'Nephrology Nursing Mock — Day 2 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Caloric control and exercise are necessary for CAPD patients because:', '["Amino acids are converted to energy", "Patients gain excess weight from being immobilized", "Fluid is more easily excreted in this way", "The dialysate contains absorbable dextrose"]'::jsonb, 3, 'The correct answer is: The dialysate contains absorbable dextrose.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 4, 'Nephrology Nursing Mock — Day 2 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'The nurse is instructing a client with diabetes mellitus about peritoneal dialysis. The nurse tells the client that it is important to maintain the dwell time for the dialysis at the prescribed time because of the risk of:', '["Hyperglycaemia", "Infection", "Disequilibrium syndrome", "Fluid overload"]'::jsonb, 0, 'The correct answer is: Hyperglycaemia.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 5, 'Nephrology Nursing Mock — Day 2 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Which of the following is NOT a complication commonly associated with peritoneal dialysis?', '["Hyperkalemia", "Peritonitis", "Hernia", "Protein loss"]'::jsonb, 0, 'Hyperkalemia is less common in peritoneal dialysis compared to hemodialysis.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 6, 'Nephrology Nursing Mock — Day 2 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Which of the following is a common immunosuppressant drug used post-transplant to prevent rejection?', '["Metoprolol", "Furosemide", "Tacrolimus", "Doxycycline"]'::jsonb, 2, 'Tacrolimus is widely used in renal transplant patients to prevent organ rejection.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 7, 'Nephrology Nursing Mock — Day 2 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Which of the following medications is commonly used as an immunosuppressant in renal transplant patients?', '["Insulin", "Cyclosporine", "Metformin", "Beta-blockers"]'::jsonb, 1, 'Cyclosporine helps prevent organ rejection in transplant patients.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 8, 'Nephrology Nursing Mock — Day 2 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'PD peritonitis is diagnosed when effluent WBC exceeds 100/µL with:', '["More than 50% neutrophils", "Normal culture only", "More than 50% lymphocytes", "Eosinophilia"]'::jsonb, 0, 'The correct answer is: More than 50% neutrophils.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 9, 'Nephrology Nursing Mock — Day 2 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'The amount of protein needed for a patient on peritoneal dialysis is:', '["0.8 g/kg body weight", "1.2-1.5 g/kg body weight", "1.0-1.2 g/kg body weight", "0.4-.6 g/kg body weight"]'::jsonb, 1, 'The correct answer is: 1.2-1.5 g/kg body weight.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
