(1, 15, 'Nephrology Nursing Mock — Day 2 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Which of the following is the access for the treatment which is used in the Peritoneal Dialysis?', '["Graft", "Catheter", "Fistula", "Dialysis Machine"]'::jsonb, 1, 'The correct answer is: Catheter.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 16, 'Nephrology Nursing Mock — Day 2 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'A common complication of peritoneal dialysis is:', '["Hypoglycemia", "Peritonitis", "Hemorrhage", "Hypercalcemia"]'::jsonb, 1, 'The correct answer is: Peritonitis.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 17, 'Nephrology Nursing Mock — Day 2 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'A client newly diagnosed with renal failure is receiving peritoneal dialysis. During the infusion of the dialysate, the client complains of abdominal pain. Which action by the nurse is most appropriate?', '["Decrease the amount to be infused", "Explain that the pain will subside after the first few exchanges", "Slow the infusion", "Stop the dialysis"]'::jsonb, 2, 'The correct answer is: Slow the infusion.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
