(1, 53, 'Nephrology Nursing Mock — Day 2 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'It is characterized by formation of scattered (segmental) mesangial sclerosis that begin in some but not all (focal) glomeruli and then eventually involves all glomeruli.', '["Minimal change nephrotic syndrome", "Nephrotic syndrome", "Focal segmental glomerulosclosis", "Obstructive uropathy"]'::jsonb, 2, 'The correct answer is: Focal segmental glomerulosclosis.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 54, 'Nephrology Nursing Mock — Day 2 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'is an inherited disorder in which clusters of cyst develop in the kidney which are noncancerous sacs containing water like fluid.', '["polycystic kidney disease", "kidney dysplasia", "segmental nephropathy", "kidney disease"]'::jsonb, 0, 'The correct answer is: polycystic kidney disease.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 55, 'Nephrology Nursing Mock — Day 2 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Contrast-induced nephropathy is best prevented by:', '["Fluid restriction before the scan", "IV hydration with isotonic fluids before and after contrast", "Fluid restriction before the scan to concentrate contrast", "Using the highest contrast dose"]'::jsonb, 1, 'Stop nephrotoxic drugs where possible.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 56, 'Nephrology Nursing Mock — Day 2 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'polycystic kidney disease are classified in to the following', '["Autosomal dominant only, as there is no recessive form of the disease", "Acquired cyst kidney disease only", "autosomal dominant only", "Autosomal dominant polycystic kidney (ADPKD), Autosomal recessive polycystic kidney and acquired cyst kidney disease (ARPKD)"]'::jsonb, 3, 'The correct answer is: Autosomal dominant polycystic kidney (ADPKD), Autosomal recessive polycystic kidney and acquired cyst kidney disease (ARPKD).', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 57, 'Nephrology Nursing Mock — Day 2 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Renal artery stenosis may cause a sudden rise in creatinine after starting:', '["Iron tablets", "Paracetamol", "Vitamin C tablets", "An ACE inhibitor"]'::jsonb, 3, 'ACE inhibitors reduce glomerular pressure.', 'NNP 421 · Medical-Surgical Nephrology II'),
