(2, 88, 'Nephrology Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Risk factors in nursing diagnostic processes', '["Represents the conditions that increase the exposure of the patient to infections", "Represent the conditions that increase the vulnerability of the patient or group to diseases", "Represent the conditions that decrease the life span of the patient or client", "Represent the situations that increase the exposure of the patient to comorbidities"]'::jsonb, 0, 'The correct answer is: Represents the conditions that increase the exposure of the patient to infections.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 89, 'Nephrology Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'The sustainable development goals consist of ?????? goals', '["15 goals", "18 goals", "16 goals", "17 goals"]'::jsonb, 3, 'The correct answer is: 17 goals.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 90, 'Nephrology Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Infant mortality rate is the of number of deaths in infants under 1 year per', '["1,000 live births for a given year", "5000 live births for a given year", "100,000 live births for a given year", "10, 000 live births for a given year"]'::jsonb, 0, 'The correct answer is: 1,000 live births for a given year.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 91, 'Nephrology Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'A patient with renal failure is being treated by a multidisciplinary team. Which team member''s role is crucial in addressing the patient''s psychosocial needs?', '["Dialysis nurse", "Nutritionist", "Nephrologist", "Social worker"]'::jsonb, 3, 'The correct answer is: Social worker.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 92, 'Nephrology Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Global health encompasses the following EXCEPT', '["Achieving better health outcomes for vulnerable populations around the world", "multidisciplinary approach to understanding emerging health challenges", "Environmental factors that underlie health inequities", "Endemic disease in one country"]'::jsonb, 3, 'The correct answer is: Endemic disease in one country.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 93, 'Nephrology Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'When discussing renal replacement therapy options with a patient, which statement should the nurse include to ensure informed decision-making?', '["\"You won''t need to make any decisions; your doctor will handle that.\"", "\"Each option has unique risks and benefits that we will discuss.\"", "\"Dialysis is always the best choice.\"", "\"Transplantation is the only long-term solution for kidney failure.\""]'::jsonb, 1, 'The correct answer is: "Each option has unique risks and benefits that we will discuss.".', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 94, 'Nephrology Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'One of these is a structural element of quality assurance within the system model', '["Treatment process", "Personnel", "Technical aspect of care", "Use of efficacious therapy"]'::jsonb, 1, 'The correct answer is: Personnel.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 95, 'Nephrology Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Which is NOT one of Roy''s adaptive modes?', '["Role function", "Self-care", "Interdependence", "Physiological"]'::jsonb, 1, 'The correct answer is: Self-care.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 96, 'Nephrology Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'One of these is NOT a determinants of quality assurance in Nursing', '["Qualification/quality of Nurse educators", "Level of nursing education/Training Institutions", "Entry requirements into education/training institutions", "Secondary school attended"]'::jsonb, 3, 'The correct answer is: Secondary school attended.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 97, 'Nephrology Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'The nephrology nurse is exploring new trends in managing chronic kidney disease. Which innovation has shown the most promise in improving patient outcomes?', '["Increased use of traditional medications", "Reduction in collaboration among healthcare providers", "Decreased emphasis on patient education", "Implementation of telehealth services"]'::jsonb, 3, 'The correct answer is: Implementation of telehealth services.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 98, 'Nephrology Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Sustainable development goals timeline is from', '["2014 to 2025", "2015 to 2030", "2013 to 2030", "2014 to 2030"]'::jsonb, 1, 'The correct answer is: 2015 to 2030.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 99, 'Nephrology Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'When reviewing a research article on new treatments for chronic kidney disease, what is the most critical question the nephrology nurse should ask?', '["How many patients were enrolled in the study?", "Is the study funded by a pharmaceutical company?", "What type of statistical analysis was used?", "What are the implications of the findings for clinical practice?"]'::jsonb, 3, 'The correct answer is: What are the implications of the findings for clinical practice?.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 100, 'Nephrology Nursing Mock — Day 2 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'A nurse implements a new evidence-based protocol for managing hyperkalemia in patients with CKD. To evaluate the effectiveness of this protocol, the nurse should:', '["Conduct an informal survey of staff opinions", "Collect anecdotal reports from patients only", "Review the protocol quarterly without specific metrics", "Monitor patient outcomes and compare them to historical data"]'::jsonb, 3, 'The correct answer is: Monitor patient outcomes and compare them to historical data.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(3, 1, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'A nephrology nurse identifies disparities in access to kidney health services. What is the first step in addressing this issue?', '["Initiating a community outreach program", "Conducting a needs assessment to understand barriers", "Reducing service availability to manage resources", "Increasing costs to filter out non-compliant patients"]'::jsonb, 1, 'The correct answer is: Conducting a needs assessment to understand barriers.', 'NNP 424 · Principles of Teaching and Management'),
(3, 2, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Which management level is responsible for policy formulation?', '["Middle managers", "Charge nurses", "Top management", "First-line managers"]'::jsonb, 2, 'Top management sets overall organisational policy and strategic direction.', 'NNP 424 · Principles of Teaching and Management'),
(3, 3, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Is the attainment of organizational goals in an effective and efficient manner through planning, organizing, staffing, directing and controlling organizational resources.', '["administration", "health management", "hospital management", "management"]'::jsonb, 3, 'The correct answer is: management.', 'NNP 424 · Principles of Teaching and Management'),
(3, 4, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'In collaborative care, which action by the nephrology nurse is essential for effective teamwork?', '["Limiting communication to scheduled meetings", "Sharing relevant patient information with all team members", "Prioritizing the physician''s input over the patient''s preferences", "Making decisions unilaterally without consulting others"]'::jsonb, 1, 'The correct answer is: Sharing relevant patient information with all team members.', 'NNP 424 · Principles of Teaching and Management'),
(3, 5, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'A nephrology nurse wishes to advocate for improved access to kidney care services. What action should they take first?', '["Speak to other nurses about their concerns only", "Focus solely on patient care without engaging in advocacy", "Gather data on patient outcomes and access issues", "Submit a proposal without any supporting evidence"]'::jsonb, 2, 'The correct answer is: Gather data on patient outcomes and access issues.', 'NNP 424 · Principles of Teaching and Management'),
(3, 6, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'The first step in an effective risk management cycle is typically to:', '["Terminate the staff member involved", "Report the incident to the media", "Identify the risk", "Implement a control plan immediately without analysis"]'::jsonb, 2, 'Risk management begins with identifying potential risks before they can be analysed, prioritised and controlled.', 'NNP 424 · Principles of Teaching and Management'),
(3, 7, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Planning is the one of the function of management which one is not among the types of planning?', '["procedure", "rule", "Meeting", "policies"]'::jsonb, 2, 'The correct answer is: Meeting.', 'NNP 424 · Principles of Teaching and Management'),
(3, 8, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Which leadership style encourages staff participation in decision-making?', '["Laissez-faire", "Democratic", "Autocratic", "Bureaucratic"]'::jsonb, 1, 'Democratic leadership actively involves staff in decision-making.', 'NNP 424 · Principles of Teaching and Management'),
(3, 9, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Which management function should always come first?', '["Controlling", "Organizing", "Directing", "Planning"]'::jsonb, 3, 'Planning sets the direction and goals that organizing, directing, and controlling all follow from, so it is the first management function.', 'NNP 424 · Principles of Teaching and Management'),
(3, 10, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Is a method of teaching where a group of students, professionals, people who gather in meeting, or conference to discuss a topic with a teacher or a professor.', '["seminar", "field trip", "play way method", "Demonstration"]'::jsonb, 0, 'The correct answer is: seminar.', 'NNP 424 · Principles of Teaching and Management'),
(3, 11, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'A ward manager notices that two nurses repeatedly clash over shift allocation, and each insists the other is at fault. She meets them separately, then jointly, and negotiates a rota both accept, though neither gets everything they wanted. Which conflict resolution strategy is this?', '["Avoidance", "Accommodation", "Compromise", "Competition"]'::jsonb, 2, 'The correct answer is: Compromise.', 'NNP 424 · Principles of Teaching and Management'),
(3, 12, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Which among the following is not the characteristics of management?', '["Management is an organized activity", "Management aims at the accomplishment of predetermined objectives", "Management is a distinct process", "management is philosophy"]'::jsonb, 3, 'The correct answer is: management is philosophy.', 'NNP 424 · Principles of Teaching and Management'),
(3, 13, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Discipline, as part of the Controlling function of management, should ideally be:', '["Used only as a first response before any coaching or feedback", "Applied inconsistently depending on personal relationships", "Avoided entirely regardless of the situation", "Fair, consistent, and applied according to established policy"]'::jsonb, 3, 'Effective disciplinary practice is fair, consistent and policy-based, typically following a progressive approach rather than being the very first response to an issue.', 'NNP 424 · Principles of Teaching and Management'),
(3, 14, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'The ICU manager knows that some of her staffs prefers to be directed rather than to be allowed to use initiative or to exercise responsibility. This statement implies:', '["Theory b", "Theory x", "Theory A", "Theory y"]'::jsonb, 1, 'Preferring direction over independent initiative reflects Theory X assumptions about workers.', 'NNP 424 · Principles of Teaching and Management'),
(3, 15, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'As an ICU manager you are aware that a formal document that most supervisors or managers keep for future reference is called', '["Incident writing", "Report writing", "Incident report", "Incident reporting"]'::jsonb, 2, 'A formal record kept by supervisors for future reference describing an event is an incident report.', 'NNP 424 · Principles of Teaching and Management'),
(3, 16, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'The five classic functions of management are best listed as:', '["Planning, Organising, Staffing, Directing, Controlling", "Hiring, Firing, Paying, Training, Promoting", "Diagnosing, Prescribing, Treating, Evaluating, Discharging", "Assessing, Planning, Implementing, Evaluating, Documenting"]'::jsonb, 0, 'The classic management functions are Planning, Organising, Staffing, Directing and Controlling.', 'NNP 424 · Principles of Teaching and Management'),
(3, 17, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Which leadership style is most appropriate during cardiopulmonary resuscitation?', '["Autocratic", "Transformational", "Laissez-faire", "Democratic"]'::jsonb, 0, 'During CPR, clear, rapid, directive instructions from one leader are needed, making autocratic leadership most appropriate in that emergency moment.', 'NNP 424 · Principles of Teaching and Management'),
(3, 18, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'When mediating conflict between staff, a nurse manager should ideally:', '["Avoid addressing it entirely", "Resolve the conflict publicly in front of patients", "Act as a neutral mediator", "Take sides with the more senior staff member"]'::jsonb, 2, 'A manager who is seen to favour one side loses the trust needed to mediate fairly between the two parties.', 'NNP 424 · Principles of Teaching and Management'),
(3, 19, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'When a nurse manager delegates a task, what remains with the delegator?', '["Authority only", "Accountability", "Responsibility only", "Nothing"]'::jsonb, 1, 'The correct answer is: Accountability.', 'NNP 424 · Principles of Teaching and Management'),
(3, 20, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Staffing is the one of the function of management which among the following is not?', '["selecting", "reporting", "training", "job function"]'::jsonb, 1, 'The correct answer is: reporting.', 'NNP 424 · Principles of Teaching and Management'),
(3, 21, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'The ''5 Rights of Delegation'' include right task, right circumstance, right person, right direction/communication, and:', '["Right uniform", "Right payment", "Right supervision/evaluation", "Right documentation only"]'::jsonb, 2, 'The 5 Rights of Delegation are: right task, right circumstance, right person, right direction/communication, and right supervision/evaluation.', 'NNP 424 · Principles of Teaching and Management'),
(3, 22, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'A nurse manager delegates a task to a staff nurse. According to the principles of delegation, what remains with the manager?', '["Only the right to supervise", "Nothing; all accountability transfers", "Nothing; all accountability transfers to the staff nurse", "Responsibility and accountability for the outcome"]'::jsonb, 3, 'The correct answer is: Responsibility and accountability for the outcome.', 'NNP 424 · Principles of Teaching and Management'),
(3, 23, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'In a quality assurance programme for renal nursing, a nursing audit committee compares actual practice against pre-set criteria and identifies gaps. Which step logically follows?', '["Punish the staff involved and close the audit file", "Problem resolution through corrective action, followed by re-evaluation", "Punish the staff involved", "Change the standards immediately"]'::jsonb, 1, 'The correct answer is: Problem resolution through corrective action, followed by re-evaluation.', 'NNP 424 · Principles of Teaching and Management'),
(3, 24, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Is "any planned performance by a presenter of an occupational skill, scientific principle or experiment is called', '["Discussion", "workshop", "demonstration", "seminar"]'::jsonb, 2, 'The correct answer is: demonstration.', 'NNP 424 · Principles of Teaching and Management'),
(3, 25, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'SBAR stands for:', '["Situation, Background, Assessment, Recommendation", "Symptom, Brief, Action, Review", "Status, Background, Alert, Report", "Situation, Behaviour, Action, Result"]'::jsonb, 0, 'The correct answer is: Situation, Background, Assessment, Recommendation.', 'NNP 424 · Principles of Teaching and Management'),
(3, 26, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Under Management by Objectives (MBO), which sequence is correct?', '["Evaluate performance, set objectives, implement, review", "Evaluate performance first, then set objectives and assign tasks", "Set organizational objectives, set individual objectives collaboratively, monitor progress, evaluate results", "Review last year''s budget, cut costs, announce targets"]'::jsonb, 2, 'The correct answer is: Set organizational objectives, set individual objectives collaboratively, monitor progress, evaluate results.', 'NNP 424 · Principles of Teaching and Management'),
(3, 27, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'In the context of improving patient outcomes, which outcome measure should be prioritized in a nephrology unit?', '["The number of patients treated per day", "Patient satisfaction scores related to care received", "Equipment utilization rates", "Equipment utilisation rates"]'::jsonb, 1, 'The correct answer is: Patient satisfaction scores related to care received.', 'NNP 424 · Principles of Teaching and Management'),
(3, 28, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'According to Herzberg''s two-factor theory, which of the following is a MOTIVATOR rather than a hygiene factor?', '["Working conditions", "Salary", "Job security", "Achievement and recognition"]'::jsonb, 3, 'The correct answer is: Achievement and recognition.', 'NNP 424 · Principles of Teaching and Management'),
(3, 29, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Which of the following is not the functions of management and administration?', '["Identification", "controlling", "planning", "organization"]'::jsonb, 0, 'The correct answer is: Identification.', 'NNP 424 · Principles of Teaching and Management'),
(3, 30, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'The renal unit director allows staff no input on a decision, issues orders, and expects strict compliance. This is which leadership style, and when is it MOST appropriate?', '["Autocratic; emergencies requiring immediate action", "Transformational; long-term change", "Laissez-faire; research teams", "Democratic; routine planning"]'::jsonb, 0, 'The correct answer is: Autocratic; emergencies requiring immediate action.', 'NNP 424 · Principles of Teaching and Management'),
(3, 31, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'Comprehensive Nephrology Revision (Dialysis, Transplant, Emergencies & Infection Control)', 'One of the statement is true for standard precaution (SP)', '["Used only to protect the health worker", "Used only when a patient has infectious disease", "Used to protect the patient from infection", "SP is used for all patients at all times"]'::jsonb, 3, 'The correct answer is: SP is used for all patients at all times.', 'Comprehensive Nephrology Revision (Dialysis, Transplant, Emergencies & Infection Control)'),
