(3, 33, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'Comprehensive Nephrology Revision (Dialysis, Transplant, Emergencies & Infection Control)', 'The best long-term treatment for most patients with end-stage kidney disease is:', '["Lifelong NSAIDs", "Bed rest", "Kidney transplantation", "Haemodialysis once a month"]'::jsonb, 2, 'It gives better survival and quality of life.', 'Comprehensive Nephrology Revision (Dialysis, Transplant, Emergencies & Infection Control)'),
(3, 34, 'Nephrology Nursing Mock — Day 2 Night (Nov 2026)', 'Comprehensive Nephrology Revision (Dialysis, Transplant, Emergencies & Infection Control)', 'Allowing disinfectant to remain wet on the surface of a medical equipment for the required amount of time is called', '["Emersion time", "Dwell time", "Contact time", "Immersion time"]'::jsonb, 2, 'The correct answer is: Contact time.', 'Comprehensive Nephrology Revision (Dialysis, Transplant, Emergencies & Infection Control)'),
